from fractions import Fraction
import math

def N(x):
    """Numerator function: x^3 + 4x^2 + 3x - 2"""
    return x**3 + 4*x**2 + 3*x - 2

def R(x):
    """Rational function: (x^3 + 4x^2 + 3x - 2) / x"""
    if x == 0:
        return None
    return N(x) / x

def is_rational_square(r_val):
    """Checks if a rational number r_val is the square of a rational number."""
    if r_val is None:
        return False
    if r_val < 0:
        return False

    # Represent r_val as a fraction to simplify analysis
    r_frac = Fraction(r_val).limit_denominator()

    # For r_frac = p/q to be a rational square, both p and q must be perfect squares
    # after the fraction is reduced to lowest terms.
    p = r_frac.numerator
    q = r_frac.denominator

    # We need to check if sqrt(p) and sqrt(q) are integers.
    # This is equivalent to checking if p and q are perfect squares.

    def is_perfect_square(n):
        if n < 0: return False
        if n == 0: return True
        root = int(math.isqrt(n))
        return root * root == n

    return is_perfect_square(p) and is_perfect_square(q)

x_values = [Fraction(1, 2), Fraction(-1, 2), Fraction(1, 3), Fraction(-1, 3), Fraction(1, 4), Fraction(-1, 4)]
results = {}

for x in x_values:
    r_x = R(x)
    is_sq = is_rational_square(r_x)
    results[x] = {
        "R(x)": r_x,
        "Is Rational Square": is_sq
    }

print("--- Test Results ---")
for x, res in results.items():
    print(f"x = {x}: R(x) = {res['R(x)']}, Is Rational Square = {res['Is Rational Square']}")
